// Original ticket from Workflow 2
const ticket = $('Execute Workflow Trigger').first().json;

// Customer lookup result (array of customers)
const customers = $('WooCommerce - Get Customer').first().json;
const customer  = Array.isArray(customers) && customers.length > 0 ? customers[0] : null;

// Orders lookup result (array of orders)
const ordersRaw = $input.first().json;
const orders    = Array.isArray(ordersRaw) ? ordersRaw : [];

// Build a readable order context string for the AI
let orderContext = 'No orders found for this customer.';
if (customer && orders.length > 0) {
  orderContext = orders.map(o => {
    const products = (o.line_items || []).map(i => i.name).join(', ');
    return `Order #${o.id} | Status: ${o.status} | Date: ${(o.date_created||'').substring(0,10)} | Total: ${o.currency} ${o.total} | Products: ${products}`;
  }).join('\n');
}

const customerName = ticket.from_name ||
  (customer ? (customer.first_name + ' ' + customer.last_name).trim() : 'Customer');

return [{
  json: {
    ...ticket,
    customer_found: !!customer,
    customer_id:    customer ? customer.id   : null,
    customer_name:  customerName,
    order_context:  orderContext
  }
}];

